:root {
  --clay: oklch(0.95 0.008 240);          /* page: wet stoneware grey */
  --paper: oklch(0.985 0.004 240);        /* raised surface */
  --ink: oklch(0.24 0.03 262);
  --muted: oklch(0.45 0.03 258);
  --rule: oklch(0.62 0.03 250);
  --cobalt: oklch(0.36 0.15 264);         /* cobalt glaze band */
  --cobalt-deep: oklch(0.27 0.11 264);
  --on-cobalt: oklch(0.96 0.01 250);
  --on-cobalt-muted: oklch(0.84 0.045 255);
  --glow: oklch(0.80 0.15 70);            /* kiln at temperature */
  --glow-hover: oklch(0.86 0.13 75);
  --ring-line: oklch(0.88 0.02 245);      /* throwing rings on light placeholders */
  --ring-line-dark: oklch(0.42 0.13 264); /* throwing rings on cobalt placeholders */

  --font-display: "Young Serif", "Rockwell", "Sitka Heading", Georgia, serif;
  --font-body: "Figtree", "Segoe UI", system-ui, -apple-system, sans-serif;

  --step--1: 0.875rem;
  --step-0: 1.0625rem;
  --step-1: 1.33rem;
  --step-2: 1.66rem;
  --step-3: 2.08rem;
  --step-4: 2.6rem;

  --space-1: 0.5rem;
  --space-2: 0.75rem;
  --space-3: 1rem;
  --space-4: 1.5rem;
  --space-5: 2.5rem;
  --space-6: 4rem;
  --space-7: 6rem;

  --radius-control: 0.5rem;
  --radius-media: 1rem;
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --gutter: clamp(1.25rem, 4vw, 3rem);
  --max: 76rem;
}

*, *::before, *::after { box-sizing: border-box; }

html {
