.btn:active { transform: translateY(1px); }
.btn-lg { min-height: 3.25rem; padding: 0.85rem 1.5rem; font-size: var(--step-1); }

.btn-glow { background: var(--glow); color: var(--ink); }
.btn-ink { background: var(--ink); color: var(--paper); }
