.section-head p { margin-top: var(--space-3); color: var(--muted); }

.firing-log {
  list-style: none;
  margin: var(--space-5) 0 0;
  padding: 0;
  border-bottom: 1px solid var(--rule);
}

.workshop {
  display: grid;
  gap: var(--space-4);
  padding: var(--space-5) 0;
  border-top: 1px solid var(--rule);
}
.workshop h3 { font-size: var(--step-2); line-height: 1.15; }
.workshop-main p { margin-top: var(--space-1); max-width: 34rem; }

.workshop-feature {
  background: var(--paper);
