  border-radius: var(--radius-media);
  border-top-color: transparent;
}
.workshop-feature + .workshop { border-top-color: transparent; }

.workshop-facts {
  margin: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(7.5rem, 1fr));
  gap: var(--space-2) var(--space-4);
  align-content: start;
}
.workshop-facts dt { font-size: var(--step--1); color: var(--muted); }
.workshop-facts dd { margin: 0; font-weight: 550; }

.workshop-book {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
}
.price { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0 var(--space-1); }
.price-num {
  font-family: var(--font-display);
  font-size: var(--step-4);
