    align-items: start;
    gap: var(--space-5);
  }
  .workshop-book {
    flex-direction: column;
    align-items: stretch;
    justify-content: flex-start;
  }
  .workshop-facts { grid-template-columns: 1fr; }
}
@media (max-width: 30rem) {
  .workshop-feature { margin-inline: calc(-1 * var(--space-3)); padding-inline: var(--space-3); }
  .workshop-book .btn { width: 100%; }
}

.booking-note {
  margin-top: var(--space-4);
  color: var(--muted);
  overflow-wrap: anywhere;
}
.booking-note a { color: var(--cobalt); font-weight: 600; }

/* ---------- Studio ---------- */
.studio {
  display: grid;
  gap: var(--space-5);
  padding-top: var(--space-6);
  padding-bottom: var(--space-7);
}
.studio-copy p { margin-top: var(--space-3); max-width: 36rem; }
.included {
  margin: var(--space-4) 0 0;
  padding-left: 1.2em;
}
.included li { padding-block: 0.2rem; }
.included li::marker { color: var(--cobalt); }

.gallery {
  display: grid;
  grid-template-columns: 1.15fr 1fr;
  gap: var(--space-4) var(--space-3);
}
.g-a { grid-row: span 2; display: flex; flex-direction: column; }
.g-a .photo { aspect-ratio: auto; flex: 1; min-height: 14rem; }
.g-d { grid-column: 1 / -1; }
.g-d .photo { aspect-ratio: 21 / 9; }

@media (max-width: 36rem) {
  .gallery { grid-template-columns: 1fr; }
  .g-a { grid-row: auto; }
  .g-a .photo { aspect-ratio: 4 / 5; flex: none; min-height: 0; }
  .g-d .photo { aspect-ratio: 4 / 3; }
}

