/* Kiln & Co. Tokens: see DESIGN.md. Contrast pairs checked in contrast.mjs. */
:root {
  --clay: oklch(0.95 0.008 240);          /* page: wet stoneware grey */
  --paper: oklch(0.985 0.004 240);        /* raised surface */
  --ink: oklch(0.24 0.03 262);
  --muted: oklch(0.45 0.03 258);
  --rule: oklch(0.62 0.03 250);
  --cobalt: oklch(0.36 0.15 264);         /* cobalt glaze band */
  --cobalt-deep: oklch(0.27 0.11 264);
  --on-cobalt: oklch(0.96 0.01 250);
  --on-cobalt-muted: oklch(0.84 0.045 255);
  --glow: oklch(0.80 0.15 70);            /* kiln at temperature */
  --glow-hover: oklch(0.86 0.13 75);
  --ring-line: oklch(0.88 0.02 245);      /* throwing rings on light placeholders */
  --ring-line-dark: oklch(0.42 0.13 264); /* throwing rings on cobalt placeholders */

  --font-display: "Young Serif", "Rockwell", "Sitka Heading", Georgia, serif;
  --font-body: "Figtree", "Segoe UI", system-ui, -apple-system, sans-serif;

  --step--1: 0.875rem;
  --step-0: 1.0625rem;
  --step-1: 1.33rem;
  --step-2: 1.66rem;
  --step-3: 2.08rem;
  --step-4: 2.6rem;

  --space-1: 0.5rem;
  --space-2: 0.75rem;
  --space-3: 1rem;
  --space-4: 1.5rem;
  --space-5: 2.5rem;
  --space-6: 4rem;
  --space-7: 6rem;

  --radius-control: 0.5rem;
  --radius-media: 1rem;
  --ease-out: cubic-bezier(0.22, 1, 0.36, 1);
  --gutter: clamp(1.25rem, 4vw, 3rem);
  --max: 76rem;
}

*, *::before, *::after { box-sizing: border-box; }

html {
  -webkit-text-size-adjust: 100%;
}
@media (prefers-reduced-motion: no-preference) {
  html { scroll-behavior: smooth; }
}

body {
  margin: 0;
  background: var(--clay);
  color: var(--ink);
  font-family: var(--font-body);
  font-size: var(--step-0);
  line-height: 1.6;
  caret-color: var(--cobalt);
}

::selection { background: var(--glow); color: var(--ink); }

h1, h2, h3 {
  font-family: var(--font-display);
  font-weight: 400;
  text-wrap: balance;
  margin: 0;
}

p { margin: 0; text-wrap: pretty; }

a { color: inherit; text-underline-offset: 0.2em; text-decoration-thickness: 0.08em; }

:focus-visible {
  outline: 3px solid var(--ink);
  outline-offset: 3px;
  border-radius: 2px;
}
.site-header :focus-visible,
.hero :focus-visible,
.site-footer :focus-visible {
  outline-color: var(--on-cobalt);
}

.skip {
  position: absolute;
  left: var(--space-3);
  top: -4rem;
  z-index: 10;
  padding: var(--space-2) var(--space-3);
  background: var(--paper);
  color: var(--ink);
  border-radius: var(--radius-control);
}
.skip:focus { top: var(--space-3); }

/* ---------- The cone (signature) ----------
   A pyrometric cone stands in the kiln and slumps when the firing is done.
   Upright = waiting. Bent = ready. Fired (footer) = done. */
.cone {
  width: 1.15em;
  height: 1.15em;
  flex: none;
  overflow: visible;
}
.cone-pad { fill: currentColor; opacity: 0.5; }
.cone-body {
  fill: currentColor;
  transform-box: view-box;
  transform-origin: 15px 20px;
  transition: transform 260ms var(--ease-out);
}
.btn:focus-visible .cone-body,
.cone-fired .cone-body { transform: rotate(62deg); }
@media (hover: hover) {
  .btn:hover .cone-body { transform: rotate(62deg); }
}
@media (prefers-reduced-motion: reduce) {
  .cone-body { transition: none; }
}

/* ---------- Buttons ---------- */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: var(--space-1);
  min-height: 2.75rem;
  padding: 0.65rem 1.15rem;
  border-radius: var(--radius-control);
  font-weight: 650;
  line-height: 1.2;
  text-decoration: none;
  touch-action: manipulation;
  transition: background-color 180ms var(--ease-out), transform 90ms var(--ease-out);
}
.btn:active { transform: translateY(1px); }
.btn-lg { min-height: 3.25rem; padding: 0.85rem 1.5rem; font-size: var(--step-1); }

.btn-glow { background: var(--glow); color: var(--ink); }
.btn-ink { background: var(--ink); color: var(--paper); }
.btn-glow:active { background: var(--glow-hover); }
.btn-ink:active { background: var(--cobalt); }
@media (hover: hover) {
  .btn-glow:hover { background: var(--glow-hover); }
  .btn-ink:hover { background: var(--cobalt); }
}
@media (prefers-reduced-motion: reduce) {
  .btn:active { transform: none; }
}

/* ---------- Header + hero: one cobalt band ---------- */
.site-header,
.hero {
  background: var(--cobalt);
  color: var(--on-cobalt);
}

.nav {
  max-width: var(--max);
  margin-inline: auto;
  padding: var(--space-3) var(--gutter);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-2) var(--space-4);
}

.wordmark {
  display: inline-flex;
  align-items: center;
  gap: 0.4rem;
  min-height: 2.75rem;
  font-family: var(--font-display);
  font-size: var(--step-1);
  text-decoration: none;
  margin-right: auto;
}
.wordmark .cone { color: var(--glow); }

.nav-links {
  list-style: none;
  margin: 0;
  padding: 0;
  display: flex;
  flex-wrap: wrap;
  gap: 0 var(--space-1);
  order: 3;
  width: 100%;
}
.nav-links a {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  padding-inline: var(--space-1);
  text-decoration: none;
  color: var(--on-cobalt);
}
.nav-links li:first-child a { padding-left: 0; }
.nav-links a:active { text-decoration: underline; }
@media (hover: hover) {
  .nav-links a:hover { text-decoration: underline; }
}
.nav-cta { padding-inline: 0.9rem; }

/* Below ~400px the hero's own CTA sits right under the nav; drop the duplicate */
@media (max-width: 26rem) {
  .nav-cta { display: none; }
}

@media (min-width: 46rem) {
  .nav-links { order: 0; width: auto; }
  .nav-links li:first-child a { padding-left: var(--space-1); }
}

.hero {
  max-width: none;
  padding: var(--space-5) var(--gutter) var(--space-7);
  display: grid;
  gap: var(--space-5);
  /* the band is full-bleed; content is held to --max by the side gutters below */
  padding-inline: max(var(--gutter), calc((100% - var(--max)) / 2 + var(--gutter)));
}

.hero h1 {
  font-size: clamp(2.6rem, 1.4rem + 5vw, 5rem);
  line-height: 1.02;
  letter-spacing: -0.01em;
  max-width: 12ch;
}
.hero-sub {
  margin-top: var(--space-4);
  max-width: 34rem;
  font-size: var(--step-1);
  line-height: 1.5;
  color: var(--on-cobalt-muted);
}
.hero-actions {
  margin-top: var(--space-5);
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: var(--space-3) var(--space-4);
}
.link-on-cobalt {
  display: inline-flex;
  align-items: center;
  min-height: 2.75rem;
  color: var(--on-cobalt);
  font-weight: 600;
}

@media (min-width: 56rem) {
  .hero {
    grid-template-columns: 1.15fr 0.85fr;
    align-items: center;
    padding-top: var(--space-6);
  }
}

@media (prefers-reduced-motion: no-preference) {
  .hero-copy > * { animation: rise 700ms var(--ease-out) both; }
  .hero-copy > :nth-child(2) { animation-delay: 90ms; }
  .hero-copy > :nth-child(3) { animation-delay: 180ms; }
  .hero-photo { animation: settle 900ms var(--ease-out) both; }
}
@keyframes rise {
  from { opacity: 0; transform: translateY(0.75rem); }
}
@keyframes settle {
  from { opacity: 0; transform: scale(0.985); }
}

/* ---------- Photo placeholders: thrown rings, not grey boxes ---------- */
figure { margin: 0; }
.photo {
  aspect-ratio: 4 / 3;
  border-radius: var(--radius-media);
  background:
    repeating-radial-gradient(circle at 50% 115%, transparent 0 13px, var(--ring-line) 13px 14px),
    var(--paper);
}
.hero .photo {
  background:
    repeating-radial-gradient(circle at 50% 115%, transparent 0 13px, var(--ring-line-dark) 13px 14px),
    var(--cobalt-deep);
}
.photo-tall { aspect-ratio: 4 / 5; }
figcaption {
  margin-top: var(--space-1);
  font-size: var(--step--1);
  color: var(--muted);
}
.hero figcaption { color: var(--on-cobalt-muted); }

/* ---------- Workshops: a firing log, not a card grid ---------- */
.workshops,
.studio {
  max-width: var(--max);
  margin-inline: auto;
  padding: var(--space-7) var(--gutter) var(--space-6);
}

.section-head { max-width: 40rem; }
.section-head h2,
.studio h2 {
  font-size: clamp(var(--step-3), 1.5rem + 2vw, var(--step-4));
  line-height: 1.1;
}
.section-head p { margin-top: var(--space-3); color: var(--muted); }

.firing-log {
  list-style: none;
  margin: var(--space-5) 0 0;
  padding: 0;
  border-bottom: 1px solid var(--rule);
}

.workshop {
  display: grid;
  gap: var(--space-4);
  padding: var(--space-5) 0;
  border-top: 1px solid var(--rule);
}
.workshop h3 { font-size: var(--step-2); line-height: 1.15; }
.workshop-main p { margin-top: var(--space-1); max-width: 34rem; }

.workshop-feature {
  background: var(--paper);
  padding-inline: var(--space-4);
  margin-inline: calc(-1 * var(--space-4));
  border-radius: var(--radius-media);
  border-top-color: transparent;
}
.workshop-feature + .workshop { border-top-color: transparent; }

.workshop-facts {
  margin: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(7.5rem, 1fr));
  gap: var(--space-2) var(--space-4);
  align-content: start;
}
.workshop-facts dt { font-size: var(--step--1); color: var(--muted); }
.workshop-facts dd { margin: 0; font-weight: 550; }

.workshop-book {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: var(--space-3);
}
.price { display: flex; flex-wrap: wrap; align-items: baseline; gap: 0 var(--space-1); }
.price-num {
  font-family: var(--font-display);
  font-size: var(--step-4);
  line-height: 1;
  font-variant-numeric: tabular-nums lining-nums;
}
.price-per { font-size: var(--step--1); color: var(--muted); }

@media (min-width: 62rem) {
  .workshop {
    grid-template-columns: minmax(0, 1.3fr) minmax(0, 1fr) 17rem;
    align-items: start;
    gap: var(--space-5);
  }
  .workshop-book {
    flex-direction: column;
    align-items: stretch;
    justify-content: flex-start;
  }
  .workshop-facts { grid-template-columns: 1fr; }
}
@media (max-width: 30rem) {
  .workshop-feature { margin-inline: calc(-1 * var(--space-3)); padding-inline: var(--space-3); }
  .workshop-book .btn { width: 100%; }
}

.booking-note {
  margin-top: var(--space-4);
  color: var(--muted);
  overflow-wrap: anywhere;
}
.booking-note a { color: var(--cobalt); font-weight: 600; }

/* ---------- Studio ---------- */
.studio {
  display: grid;
  gap: var(--space-5);
  padding-top: var(--space-6);
  padding-bottom: var(--space-7);
}
.studio-copy p { margin-top: var(--space-3); max-width: 36rem; }
.included {
  margin: var(--space-4) 0 0;
  padding-left: 1.2em;
}
.included li { padding-block: 0.2rem; }
.included li::marker { color: var(--cobalt); }

.gallery {
  display: grid;
  grid-template-columns: 1.15fr 1fr;
  gap: var(--space-4) var(--space-3);
}
.g-a { grid-row: span 2; display: flex; flex-direction: column; }
.g-a .photo { aspect-ratio: auto; flex: 1; min-height: 14rem; }
.g-d { grid-column: 1 / -1; }
.g-d .photo { aspect-ratio: 21 / 9; }

@media (max-width: 36rem) {
  .gallery { grid-template-columns: 1fr; }
  .g-a { grid-row: auto; }
  .g-a .photo { aspect-ratio: 4 / 5; flex: none; min-height: 0; }
  .g-d .photo { aspect-ratio: 4 / 3; }
}

@media (min-width: 62rem) {
  .studio {
    grid-template-columns: minmax(0, 0.8fr) minmax(0, 1.2fr);
    gap: var(--space-6);
    align-items: start;
  }
}

/* ---------- Footer ---------- */
.site-footer {
  background: var(--cobalt-deep);
  color: var(--on-cobalt);
  padding: var(--space-6) var(--gutter) var(--space-4);
}
.footer-grid {
  max-width: var(--max);
  margin-inline: auto;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(13rem, 1fr));
  gap: var(--space-5) var(--space-4);
}
.site-footer h2 {
  font-family: var(--font-body);
  font-size: var(--step-0);
  font-weight: 650;
  margin-bottom: var(--space-1);
}
.site-footer p,
.site-footer address {
  font-style: normal;
  color: var(--on-cobalt-muted);
  overflow-wrap: anywhere;
}
.site-footer a {
  color: var(--glow);
  display: inline-block;
  padding-block: 0.6rem;
  margin-block: -0.6rem;
}
.site-footer .wordmark-footer {
  font-size: var(--step-2);
  color: var(--on-cobalt);
  margin: 0 0 var(--space-1);
  min-height: 0;
}
.wordmark-footer .cone { color: var(--glow); }
.small-print {
  max-width: var(--max);
  margin: var(--space-6) auto 0;
  padding-top: var(--space-3);
  border-top: 1px solid var(--cobalt);
  font-size: var(--step--1);
}
